function _update(address account, uint256[] memory ids, uint256 bpf) internal {
    uint256 amount = __update(account, ids, bpf);
    if (amount > 0) IBS(owner()).payFertilizer(account, amount);
}

findings.proof_of_concept:
function test_reentrancy_fertilizer_roundTrip() public {
    // Attacker holds Fertilizer (ids with owed sprouts), recipient is an onERC1155Received contract.
    // Action: call Fertilizer.safeTransferFrom(attacker, attackerContract, id, amount).
    //   _beforeTokenTransfer -> _update -> payFertilizer (Beans To.INTERNAL); then _transfer; then onERC1155Received.
